$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""
$helper = Decode ""
$checkoutApi = Decode ""
$webhook = Decode ""
$groupPage = Decode ""

$migrationPath = Join-Path $root "supabase\migrations\20260812203500_klyx_group_payment_12_86.sql"
$helperPath = Join-Path $root "lib\stripe-group-payments.ts"
$checkoutPath = Join-Path $root "app\api\stripe\create-group-checkout-session\route.ts"
$webhookPath = Join-Path $root "app\api\stripe\webhook\route.ts"
$pagePath = Join-Path $root "app\booking-groups\[id]\page.tsx"

foreach ($path in @($webhookPath, $pagePath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Fichier requis introuvable : $path"
    }
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $migrationPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $helperPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $checkoutPath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($webhookPath, $pagePath)) {
    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-86-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)
[System.IO.File]::WriteAllText($helperPath, $helper, $utf8)
[System.IO.File]::WriteAllText($checkoutPath, $checkoutApi, $utf8)
[System.IO.File]::WriteAllText($webhookPath, $webhook, $utf8)
[System.IO.File]::WriteAllText($pagePath, $groupPage, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.86 APPLIQUE"
Write-Host "======================================"
Write-Host "Checkout groupe unique : OK"
Write-Host "Protection double paiement : OK"
Write-Host "Webhook groupe : OK"
Write-Host "Reservations enfants synchronisees : OK"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
Write-Host ""
